#include <Wire.h>
#include <LiquidCrystal_I2C.h>
LiquidCrystal_I2C lcd(0x27,16,2); void setup(){lcd.init();lcd.backlight();lcd.print("Hello COMs!");} void loop(){static int n=0;lcd.setCursor(0,1);lcd.print(n++);lcd.print("    ");delay(1000);}

dht-lcd.code:
#include <Wire.h>
#include <LiquidCrystal_I2C.h>
#include <DHT.h>
DHT dht(2,DHT11); LiquidCrystal_I2C lcd(0x27,16,2); void setup(){Serial.begin(9600);dht.begin();lcd.init();lcd.backlight();} void loop(){float t=dht.readTemperature(),h=dht.readHumidity();if(!isnan(t)&&!isnan(h)){Serial.print(t);Serial.print(" C ");Serial.println(h);lcd.clear();lcd.print("Temp:");lcd.print(t);lcd.setCursor(0,1);lcd.print("Humidity:");lcd.print(h);}delay(2000);}
